package io.github.ningpp.compat;

/** Replacement for System.Text.RegularExpressions.RegexMatchTimeoutException (generated by CSharpToJava converter). */
public class RegexMatchTimeoutException extends TimeoutException {
    public RegexMatchTimeoutException() { super(); }
    public RegexMatchTimeoutException(String message) { super(message); }
    public RegexMatchTimeoutException(String message, Throwable cause) { super(message, cause); }
}
